import os
import torch


class Config:
    """
    Global configuration for the Pet Pawpularity Prediction pipeline.
    """

    # ==========================================
    # 1. Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # 2. File Paths
    # ==========================================
    # Base directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"

    # Metadata paths (Generated by metadata script)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train_meta.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val_meta.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test_meta.csv")

    # Cache paths for extracted features (npy format)
    # These allow us to skip the expensive CNN pass on subsequent runs
    CACHE_TRAIN_FEATURES = os.path.join(WORKING_DIR, "train_features.npy")
    CACHE_TRAIN_TARGETS = os.path.join(WORKING_DIR, "train_targets.npy")
    CACHE_TRAIN_META = os.path.join(WORKING_DIR, "train_meta_features.npy")

    CACHE_VAL_FEATURES = os.path.join(WORKING_DIR, "val_features.npy")
    CACHE_VAL_TARGETS = os.path.join(WORKING_DIR, "val_targets.npy")
    CACHE_VAL_META = os.path.join(WORKING_DIR, "val_meta_features.npy")

    CACHE_TEST_FEATURES = os.path.join(WORKING_DIR, "test_features.npy")
    CACHE_TEST_IDS = os.path.join(WORKING_DIR, "test_ids.npy")
    CACHE_TEST_META = os.path.join(WORKING_DIR, "test_meta_features.npy")

    # Final submission path
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 3. Hyperparameters
    # ==========================================
    # Data Processing
    IMG_SIZE = 224  # MobileNetV2 requires 224x224
    BATCH_SIZE = 64  # Batch size for feature extraction
    NUM_WORKERS = 2  # Number of DataLoader workers

    # Model (MLP)
    MLP_HIDDEN_DIM = 256
    MLP_DROPOUT = 0.3
    MLP_LR = 1e-3
    MLP_WEIGHT_DECAY = 1e-5
    MLP_EPOCHS = 30
    MLP_BATCH_SIZE = 64

    # Debugging
    DEBUG = False  # Set to True to use a small subset of data
    DEBUG_SUBSET_SIZE = 100  # Number of samples to use when DEBUG is True

    # ==========================================
    # 4. Device Configuration
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Creates necessary output directories if they don't exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories on module import
Config.setup()
